#include <torch/extension.h>
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "acl/acl.h"
#include "catlass/arch/arch.hpp"
#include "catlass/catlass.hpp"
#include "catlass/gemm/block/block_mmad.hpp"
#include "catlass/gemm/block/block_swizzle.hpp"
#include "catlass/gemm/device/device_gemm.hpp"
#include "catlass/gemm/dispatch_policy.hpp"
#include "catlass/gemm/gemm_type.hpp"
#include "catlass/gemm/kernel/matmul_bias.hpp"
#include "catlass/layout/layout.hpp"
#include "catlass/status.hpp"
#include "kernel_operator.h"
#include "tiling/platform/platform_ascendc.h"

using namespace Catlass;

namespace cpp_extension_acs {

at::Tensor catlass_gemm_bias(const at::Tensor &a, const at::Tensor &b, const at::Tensor &bias) {
    TORCH_CHECK(a.dtype() == torch::kHalf, "Input a must be half type");
    TORCH_CHECK(b.dtype() == torch::kHalf, "Input b must be half type");
    TORCH_CHECK(bias.dtype() == torch::kHalf, "Input bias must be half type");
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "Only support 2D matmul");
    TORCH_CHECK(a.size(1) == b.size(0), "Matrix shape mismatch");
    TORCH_CHECK(bias.size(0) == b.size(1), "Bias shape mismatch");

    uint32_t M = static_cast<uint32_t>(a.size(0));
    uint32_t N = static_cast<uint32_t>(b.size(1));
    uint32_t K = static_cast<uint32_t>(a.size(1));

    auto output = at::empty({static_cast<int64_t>(M), static_cast<int64_t>(N)}, a.options());

    using LayoutA = layout::RowMajor;
    using LayoutB = layout::RowMajor;
    using LayoutC = layout::RowMajor;
    using LayoutBias = layout::VectorLayout;

    using ArchTag = Arch::AtlasA2;
    using DispatchPolicy = Gemm::MmadAtlasA2PingpongBias<true>;
    using L1TileShape = GemmShape<128, 256, 256>;
    using L0TileShape = GemmShape<128, 256, 64>;

    using AType = Gemm::GemmType<half, LayoutA>;
    using BType = Gemm::GemmType<half, LayoutB>;
    using CType = Gemm::GemmType<half, LayoutC>;
    using BiasType = Gemm::GemmType<half, LayoutBias>;

    using BlockMmad = Gemm::Block::BlockMmad<DispatchPolicy, L1TileShape, L0TileShape, AType, BType, CType, BiasType>;
    using BlockEpilogue = void;
    using BlockScheduler = typename Gemm::Block::GemmIdentityBlockSwizzle<3, 0>;

    using MatmulKernel = Gemm::Kernel::MatmulBias<BlockMmad, BlockEpilogue, BlockScheduler>;
    using MatmulAdapter = Gemm::Device::DeviceGemm<MatmulKernel>;

    GemmCoord problemShape{M, N, K};
    uint8_t* deviceA = static_cast<uint8_t*>(a.data_ptr());
    uint8_t* deviceB = static_cast<uint8_t*>(b.data_ptr());
    uint8_t* deviceC = static_cast<uint8_t*>(output.data_ptr());
    uint8_t* deviceBias = static_cast<uint8_t*>(const_cast<void*>(bias.data_ptr()));

    typename MatmulKernel::Arguments arguments{problemShape, deviceA, deviceB, deviceC, deviceBias};
    MatmulAdapter matmulOp;
    matmulOp.CanImplement(arguments);

    size_t sizeWorkspace = matmulOp.GetWorkspaceSize(arguments);
    uint8_t* deviceWorkspace = nullptr;
    if (sizeWorkspace > 0) {
        aclrtMalloc(reinterpret_cast<void**>(&deviceWorkspace), sizeWorkspace, ACL_MEM_MALLOC_HUGE_FIRST);
    }

    aclrtStream stream = c10_npu::getCurrentNPUStream();
    auto aicCoreNum = platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAic();

    matmulOp.Initialize(arguments, deviceWorkspace);
    matmulOp(stream, aicCoreNum);

    if (sizeWorkspace > 0) {
        aclrtFree(deviceWorkspace);
    }

    return output;
}

}

at::Tensor gemm_bias_impl_meta(const at::Tensor &a, const at::Tensor &b, const at::Tensor &bias) {
    return at::empty({a.size(0), b.size(1)}, a.options());
}

TORCH_LIBRARY_FRAGMENT(cpp_extension_acs, m) {
    m.def("catlass_gemm_bias(Tensor a, Tensor b, Tensor bias) -> Tensor");
}
TORCH_LIBRARY_IMPL(cpp_extension_acs, PrivateUse1, m) {
    m.impl("catlass_gemm_bias", TORCH_FN(cpp_extension_acs::catlass_gemm_bias));
}
TORCH_LIBRARY_IMPL(cpp_extension_acs, Meta, m) {
    m.impl("catlass_gemm_bias", &gemm_bias_impl_meta);
}

import torch
import torch_npu

def run(a, b, bias):
    return torch.ops.cpp_extension_acs.catlass_gemm_bias(a, b, bias)
